using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------- configuration ----------
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptUser("Enter a research topic: ");

Console.WriteLine($"\n🔍  Researching: {topic}\n");

// ---------- tools ----------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) => WebSearch.SearchAsync(query),
        "web_search",
        "Searches the web for a query and returns a list of result snippets."),
    AIFunctionFactory.Create(
        ([Description("The note text to save")] string note) => notebook.AddNote(note),
        "save_note",
        "Saves an important finding as a note for later reference."),
    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "read_notes",
        "Reads back all notes saved so far."),
};

// ---------- chat client ----------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic
        by searching the web multiple times with varied queries, saving important
        findings as notes, and finally producing a well-structured summary.

        Follow this workflow:
        1. Break the topic into 2-4 sub-questions.
        2. Search the web for each sub-question.
        3. Save the most important facts using save_note.
        4. After gathering enough information, read your notes and write a
           comprehensive summary with key findings and sources.
        5. Present the final summary to the user (do NOT call any more tools after
           the summary).
        """),
    new(ChatRole.User, $"Research this topic: {topic}"),
};

// ---------- agent loop ----------
const int maxIterations = 20;
for (int i = 0; i < maxIterations; i++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);
    messages.Add(response.Message);

    if (response.Message.Contents.OfType<FunctionCallContent>().Any())
    {
        foreach (var call in response.Message.Contents.OfType<FunctionCallContent>())
        {
            Console.WriteLine($"  🛠  {call.Name}({Summarize(call.Arguments)})");
            var result = await call.InvokeAsync(tools);
            messages.Add(result.ToChatMessage(call.CallId));
        }
    }
    else
    {
        // No tool calls means the agent is done — print final answer.
        Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
        Console.WriteLine(response.Message.Text);
        Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
        break;
    }
}

// ---------- helpers ----------
static string PromptUser(string prompt)
{
    Console.Write(prompt);
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input) ? "latest advances in quantum computing" : input;
}

static string Summarize(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    var first = args.Values.First();
    var s = first?.ToString() ?? "";
    return s.Length > 80 ? s[..77] + "..." : s;
}

// ================================================================
//  Notebook – simple in-memory note-taking tool
// ================================================================
sealed class Notebook
{
    private readonly List<string> _notes = [];

    public string AddNote(string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0) return "(no notes yet)";
        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }
}

// ================================================================
//  WebSearch – lightweight web search via DuckDuckGo HTML
// ================================================================
static partial class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        }
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
            var html = await Http.GetStringAsync(url);
            var results = ExtractSnippets(html);
            return results.Length > 0
                ? results
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    private static string ExtractSnippets(string html)
    {
        var sb = new StringBuilder();
        int count = 0;

        // Extract result snippets from DuckDuckGo HTML response
        foreach (Match m in SnippetRegex().Matches(html))
        {
            if (count >= 5) break;
            var text = StripHtml(WebUtility.HtmlDecode(m.Groups[1].Value)).Trim();
            if (text.Length < 20) continue;
            count++;
            sb.AppendLine($"[{count}] {text}");
        }

        // Fallback: extract any <a> result links with surrounding text
        if (count == 0)
        {
            foreach (Match m in LinkTextRegex().Matches(html))
            {
                if (count >= 5) break;
                var text = StripHtml(WebUtility.HtmlDecode(m.Groups[1].Value)).Trim();
                if (text.Length < 10) continue;
                count++;
                sb.AppendLine($"[{count}] {text}");
            }
        }

        return sb.ToString();
    }

    private static string StripHtml(string html) => HtmlTagRegex().Replace(html, "");

    [GeneratedRegex("""<a class="result__snippet"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("""<a class="result__a"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
    private static partial Regex LinkTextRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();
}

