    }
}

arguments.new_str:
// ---------- agent loop ----------
const int maxIterations = 20;
for (int i = 0; i < maxIterations; i++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);

    // Add all response messages to history
    foreach (var msg in response.Messages)
        messages.Add(msg);

    // Collect tool calls from all response messages
    var toolCalls = response.Messages
        .SelectMany(m => m.Contents.OfType<FunctionCallContent>())
        .ToList();

    if (toolCalls.Count > 0)
    {
        var resultContents = new List<AIContent>();
        foreach (var call in toolCalls)
        {
            Console.WriteLine($"  🛠  {call.Name}({Summarize(call.Arguments)})");
            var result = await call.InvokeAsync(tools);
            resultContents.Add(new FunctionResultContent(call.CallId, result));
        }

        var toolResultMessage = new ChatMessage(ChatRole.Tool, resultContents);
        messages.Add(toolResultMessage);
    }
    else
    {
        // No tool calls means the agent is done — print final answer.
        Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
