48. {
49.     new(ChatRole.System, """
50.         You are a research agent. Your goal is to thoroughly research the given topic
51.         by searching the web multiple times with varied queries, saving important
52.         findings as notes, and finally producing a well-structured summary.
53. 
54.         Follow this workflow:
55.         1. Break the topic into 2-4 sub-questions.
56.         2. Search the web for each sub-question.
57.         3. Save the most important facts using save_note.
58.         4. After gathering enough information, read your notes and write a
59.            comprehensive summary with key findings and sources.
60.         5. Present the final summary to the user (do NOT call any more tools after
61.            the summary).
62.         """),
63.     new(ChatRole.User, $"Research this topic: {topic}"),
64. };
65. 
66. // ---------- agent loop ----------
67. const int maxIterations = 20;
68. for (int i = 0; i < maxIterations; i++)
69. {
70.     var response = await client.GetResponseAsync(messages, chatOptions);
71. 
72.     // Add all response messages to history
73.     foreach (var msg in response.Messages)
74.         messages.Add(msg);
75. 
76.     // Collect tool calls from all response messages
77.     var toolCalls = response.Messages
78.         .SelectMany(m => m.Contents.OfType<FunctionCallContent>())
79.         .ToList();
80. 
81.     if (toolCalls.Count > 0)
82.     {
83.         var resultContents = new List<AIContent>();
84.         foreach (var call in toolCalls)
85.         {
86.             Console.WriteLine($"  🛠  {call.Name}({Summarize(call.Arguments)})");
87.             var fn = tools.OfType<AIFunction>().FirstOrDefault(f => f.Name == call.Name);
88.             object? result;
89.             if (fn is not null)
90.             {
91.                 var fnArgs = new AIFunctionArguments(call.Arguments ?? new Dictionary<string, object?>());
92.                 result = await fn.InvokeAsync(fnArgs);
93.             }
94.             else
95.             {
96.                 result = $"Unknown tool: {call.Name}";
97.             }
98.             resultContents.Add(new FunctionResultContent(call.CallId, result));
99.         }
100. 
101.         var toolResultMessage = new ChatMessage(ChatRole.Tool, resultContents);
102.         messages.Add(toolResultMessage);
103.     }
104.     else
105.     {
106.         // No tool calls means the agent is done — print final answer.
107.         Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
