114. // ---------- helpers ----------
115. static string PromptUser(string prompt)
116. {
117.     Console.Write(prompt);
118.     var input = Console.ReadLine()?.Trim();
119.     return string.IsNullOrEmpty(input) ? "latest advances in quantum computing" : input;
120. }
121. 
122. static string Summarize(IDictionary<string, object?>? args)
123. {
124.     if (args is null || args.Count == 0) return "";
125.     var first = args.Values.First();
126.     var s = first?.ToString() ?? "";
127.     return s.Length > 80 ? s[..77] + "..." : s;
128. }
129. 
130. // ================================================================
131. //  Notebook – simple in-memory note-taking tool
132. // ================================================================
133. sealed class Notebook
134. {
135.     private readonly List<string> _notes = [];
136. 
137.     public string AddNote(string note)
138.     {
139.         _notes.Add(note);
140.         return $"Note #{_notes.Count} saved.";
141.     }
142. 
143.     public string GetNotes()
144.     {
145.         if (_notes.Count == 0) return "(no notes yet)";
146.         var sb = new StringBuilder();
147.         for (int i = 0; i < _notes.Count; i++)
148.             sb.AppendLine($"[{i + 1}] {_notes[i]}");
149.         return sb.ToString();
150.     }
151. }
152. 
153. // ================================================================
154. //  WebSearch – lightweight web search via DuckDuckGo HTML
155. // ================================================================
156. static partial class WebSearch
157. {
158.     private static readonly HttpClient Http = new()
159.     {
160.         DefaultRequestHeaders =
161.         {
162.             { "User-Agent", "ResearchAgent/1.0" }
163.         }
164.     };
165. 
166.     public static async Task<string> SearchAsync(string query)
167.     {
168.         try
169.         {
170.             var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
171.             var html = await Http.GetStringAsync(url);
172.             var results = ExtractSnippets(html);
173.             return results.Length > 0
174.                 ? results
175.                 : "No results found. Try a different query.";
176.         }
177.         catch (Exception ex)
178.         {
179.             return $"Search failed: {ex.Message}. Try a different query.";
180.         }
181.     }
182. 
183.     private static string ExtractSnippets(string html)
184.     {
185.         var sb = new StringBuilder();
186.         int count = 0;
187. 
188.         // Extract result snippets from DuckDuckGo HTML response
189.         foreach (Match m in SnippetRegex().Matches(html))
190.         {
191.             if (count >= 5) break;
192.             var text = StripHtml(WebUtility.HtmlDecode(m.Groups[1].Value)).Trim();
193.             if (text.Length < 20) continue;
194.             count++;
195.             sb.AppendLine($"[{count}] {text}");
196.         }
197. 
198.         // Fallback: extract any <a> result links with surrounding text
199.         if (count == 0)
200.         {
201.             foreach (Match m in LinkTextRegex().Matches(html))
202.             {
203.                 if (count >= 5) break;
204.                 var text = StripHtml(WebUtility.HtmlDecode(m.Groups[1].Value)).Trim();
205.                 if (text.Length < 10) continue;
206.                 count++;
207.                 sb.AppendLine($"[{count}] {text}");
208.             }
209.         }
210. 
211.         return sb.ToString();
212.     }
213. 
214.     private static string StripHtml(string html) => HtmlTagRegex().Replace(html, "");
215. 
216.     [GeneratedRegex("""<a class="result__snippet"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
217.     private static partial Regex SnippetRegex();
218. 
219.     [GeneratedRegex("""<a class="result__a"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
220.     private static partial Regex LinkTextRegex();
221. 
222.     [GeneratedRegex("<[^>]+>")]
223.     private static partial Regex HtmlTagRegex();
224. }
